import { useEffect } from "react";

import { SectionOutlet, useLocation, useNavigate } from "@huspy/fe";

const OPS_QUEUE_PATH = "/ops-queue";

export function CreditOpsHomePage() {
  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    if (location.pathname === "/") {
      navigate(OPS_QUEUE_PATH, { replace: true });
    }
  }, [location.pathname, navigate]);

  return (
    <div className="bg-background min-h-screen">
      <SectionOutlet />
    </div>
  );
}
